from pathlib import Path
import argparse,json,hashlib,subprocess,time
p=argparse.ArgumentParser()
for n in ('executable','sdk-directory','supervisor','node','directory'):p.add_argument('--'+n,type=Path,required=True)
a=p.parse_args();root=a.directory;root.mkdir(exist_ok=False);pins={str(x):hashlib.sha256(x.read_bytes()).hexdigest() for x in [Path(__file__).resolve(),a.executable.resolve(),a.node.resolve(),a.supervisor.resolve(),*sorted(a.sdk_directory.glob('*.js'))]};groups=[]
for count,workers in ((2,1),(2,2),(8,1),(8,8)):
 case=root/(str(count)+'-files-workers'+str(workers));tests=case/'tests';tests.mkdir(parents=True)
 for n in range(count):(tests/(str(n)+'.spec.mjs')).write_text('import {defineNativeSuite} from '+json.dumps((a.sdk_directory/'native-suite.js').as_uri())+';export default defineNativeSuite({fixtures:{actual:{scope:"worker",setup:async(_,use)=>{await use(process.pid)}}},tests:[{title:"actual file callback",fixtures:["actual"],run:({actual})=>{if(actual!==process.pid)throw Error("foreign host")}}]});\n')
 cmd=[str(a.supervisor),'--report',str(case/'supervisor.json'),'--timeout-ms','45000','--cleanup-grace-ms','1000','--physical-ms','10000','--',str(a.node),str(a.sdk_directory/'native-runner-cli.js'),'--executable',str(a.executable),'--test-dir',str(tests),'--report',str(case/'actual.json'),'--workers',str(workers)];start=time.monotonic_ns()
 with (case/'stdout').open('wb') as out,(case/'stderr').open('wb') as err:r=subprocess.run(cmd,stdout=out,stderr=err)
 wall=time.monotonic_ns()-start;physical=json.loads((case/'supervisor.json').read_text());report=json.loads((case/'actual.json').read_text());d=report['directory'];assert r.returncode==0 and report['summary']['expected']==count and not physical['cleanupFailed'] and not physical['timeout'] and physical['descendantsRetired'] and (case/'stderr').read_bytes()==b''
 collections=[c['timing'] for c in d['collections']];execution=[s['timing'] for s in d['segments'] if s['sourceId']];hosts=[h for t in collections+execution for h in t['hosts']];pids={physical['childPID'],d['coordinatorPID'],*[h['pid'] for h in hosts]};remaining=[pid for pid in pids if Path('/proc',str(pid)).exists()];assert not remaining
 observed={'directoryPreludeUntilFirstCollectionMs':min(t['actorAdmittedMonotonicMs'] for t in collections)-d['originalStartMonotonicMs'],'collectionWallMs':max(t['actorCompletedMonotonicMs'] for t in collections)-min(t['actorAdmittedMonotonicMs'] for t in collections),'executionCohortsWallMs':max(t['actorCompletedMonotonicMs'] for t in execution)-min(t['actorAdmittedMonotonicMs'] for t in execution),'hostAdmissionToMetadataSumMs':sum(h['metadataDecodedMonotonicMs']-h['admittedMonotonicMs'] for h in hosts if h['metadataDecodedMonotonicMs'] is not None),'closeRequestToActualWaitpidCaptureSumMs':sum(h['waitpidCapturedMonotonicMs']-h['closeStartedMonotonicMs'] for h in hosts if h['closeStartedMonotonicMs'] is not None)}
 groups.append({'files':count,'workers':workers,'totalWallNs':wall,'nativePhases':observed,'actualHostCount':len(hosts),'actualPIDs':sorted(pids),'remainingPIDs':remaining,'supervisor':physical,'report':str(case/'actual.json')});changed=[p for p,h in pins.items() if hashlib.sha256(Path(p).read_bytes()).hexdigest()!=h];assert not changed;(root/'index.json').write_text(json.dumps({'scope':'Same binary/SDK/inventory 2/8 file workers1 vs workers2/8 measurement; no native/author timeout changed. Native decoded-metadata span includes import+parser; close span includes fixture/descendant retirement. Sum spans can overlap and are not walltime.','inputs':pins,'changed':changed,'groups':groups},indent=2)+'\n');print(count,workers,round(wall/1e9,3),observed,flush=True)
